function recommendPD(scope='',appointment=''){
 const t=(scope+' '+appointment).toLowerCase();
 const cdm=/\bcdm\b|construction design and management/.test(t);
 const br=/building regulations principal designer|building regs principal designer|brpd/.test(t);
 if((cdm&&br)||/combined.*principal designer|both.*principal designer/.test(t))return 'PD05';
 if(cdm)return 'PD03';
 if(br)return 'PD04';
 if(/site inspection|site visit|compliance visit/.test(t))return 'PD06';
 if(/technical drawings|building regulations drawings|construction details|technical design|building control drawings/.test(t))return 'PD02';
 return 'PD01';
}
