async function save(e,planUpload){e.preventDefault();const {estimate_type,builder_id,...fields}=form;const payload={...fields,estimate_data:{builder_id:builder_id||''},project_no:form.project_no||nextProjectNumber(projects),scope:estimate_type?('Building type: '+estimate_type+(fields.scope?'\n'+fields.scope:'')):fields.scope,base_price:form.base_price?Number(form.base_price):null};const{data,error}=await db.from('projects').insert(payload).select().single();if(error){setMsg(error.message);throw Error(error.message)}const failures=[];for(const [i,file] of (planUpload?.files||[]).entries()){const safe=file.name.replace(/[^a-zA-Z0-9._-]/g,'_'),path=data.id+'/documents/'+Date.now()+'-'+i+'-'+safe;const uploaded=await db.storage.from('project-files').upload(path,file);if(uploaded.error){failures.push(file.name+': '+uploaded.error.message);continue}const recorded=await db.from('documents').insert({project_id:data.id,document_type:'Plans / Drawings',document_no:file.name,title:file.name,revision:'Uploaded',status:'Current',verification_status:'Awaiting PD Review',file_path:path,paper_size:planUpload.paperSize,drawing_scale:planUpload.drawingScale});if(recorded.error){failures.push(file.name+': '+recorded.error.message);await db.storage.from('project-files').remove([path])}}setModal(false);setForm(blank);await load();setActive(data);setPage('Projects');if(failures.length){setMsg('Project created, but '+failures.length+' plan(s) failed to upload: '+failures.join('; '));alert('Project created. Some plans could not be uploaded. Please retry them from Upload Plans.\n'+failures.join('\n'))}else if(planUpload?.files?.length){setMsg('Project created with '+planUpload.files.length+' drawing(s) uploaded.')}return data}
